package com.kuzhi.findme.client;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

final class CompanionTeamSelectionDraft {
    private final int capacity;
    private List<UUID> original = List.of();
    private final List<UUID> selected = new ArrayList<UUID>();
    private List<UUID> displayOrder = List.of();

    CompanionTeamSelectionDraft(int capacity) {
        this.capacity = Math.max(0, capacity);
    }

    void begin(List<UUID> members, List<UUID> availableMembers) {
        this.original = members == null ? List.of() : members.stream().filter(Objects::nonNull).distinct().limit(this.capacity).toList();
        this.selected.clear();
        this.selected.addAll(this.original);
        ArrayList<UUID> order = new ArrayList<UUID>(this.original);
        if (availableMembers != null) {
            availableMembers.stream().filter(Objects::nonNull).filter(uuid -> !order.contains(uuid)).forEach(order::add);
        }
        this.displayOrder = List.copyOf(order);
    }

    void clear() {
        this.original = List.of();
        this.selected.clear();
        this.displayOrder = List.of();
    }

    boolean toggle(UUID uuid) {
        if (uuid == null) {
            return false;
        }
        if (this.selected.remove(uuid)) {
            return true;
        }
        if (this.selected.size() >= this.capacity) {
            return false;
        }
        this.selected.add(uuid);
        return true;
    }

    boolean contains(UUID uuid) {
        return this.selected.contains(uuid);
    }

    boolean full() {
        return this.selected.size() >= this.capacity;
    }

    boolean changed() {
        return !this.original.equals(this.selected);
    }

    int size() {
        return this.selected.size();
    }

    List<UUID> selected() {
        return List.copyOf(this.selected);
    }

    List<UUID> original() {
        return this.original;
    }

    List<UUID> displayOrder() {
        return this.displayOrder;
    }
}

